<?php

declare(strict_types=1);

namespace Koravik\Districts\Beacon;

use Koravik\Platform\Database\Database;
use Koravik\Platform\Security\Security;
use RuntimeException;

final class BeaconController
{
    public function __construct(private readonly Database $database) {}

    public function handle(string $method,string $path): bool
    {
        $host=strtolower((string)($_SERVER['HTTP_HOST']??''));$domains=new BeaconDomainService($this->database);$domain=$domains->resolveHost($host);
        if($method==='GET'&&$domain){
            if($path==='/'){$target=(string)($domain['root_redirect_url']??'');if($target!==''){header('Location: '.$target,true,301);exit;}return false;}
            if(preg_match('#^/([a-z0-9-]+)$#',$path,$m)){$row=$domains->resolveLink($host,$m[1]);if($row){header('Location: '.(string)$row['destination_url'],true,302);exit;}http_response_code(404);echo $this->page('Link not found','<section class="empty-state"><h1>This Beacon is unavailable.</h1></section>');return true;}
        }
        if($method==='GET'&&$path==='/beacon'){$this->indexV2();return true;}
        if($method==='POST'&&$path==='/beacon/actions'){$this->createActionBeacon();return true;}
        if($method==='POST'&&$path==='/beacon/links'){$this->createLink();return true;}
        if($method==='POST'&&$path==='/beacon/pages'){$this->createPage();return true;}
        if($method==='POST'&&$path==='/beacon/campaigns'){$this->createCampaign();return true;}
        if($method==='GET'&&preg_match('#^/beacon/campaigns/([a-f0-9-]{36})$#',$path,$m)){$this->campaign($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/beacon/campaigns/([a-f0-9-]{36})$#',$path,$m)){$this->updateCampaign($m[1]);return true;}
        if($method==='GET'&&preg_match('#^/beacon/pages/([a-f0-9-]{36})/edit$#',$path,$m)){$this->editPageV2($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/beacon/pages/([a-f0-9-]{36})$#',$path,$m)){$this->updatePage($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/beacon/pages/([a-f0-9-]{36})/blocks$#',$path,$m)){$this->addBlock($m[1]);return true;}
        if($method==='POST'&&preg_match('#^/beacon/pages/([a-f0-9-]{36})/blocks/([a-f0-9-]{36})/(up|down)$#',$path,$m)){$this->moveBlock($m[1],$m[2],$m[3]);return true;}
        if($method==='GET'&&preg_match('#^/b/([a-z0-9]+)$#',$path,$m)){$this->redirectLink($m[1]);return true;}
        if($method==='GET'&&preg_match('#^/p/([a-z0-9]+)$#',$path,$m)){$this->publicPage($m[1]);return true;}
        return false;
    }

    private function index(): void
    {
        $a=Security::requireAccount();$data=(new BeaconService($this->database))->dashboard((string)$a['id']);
        $links='';foreach($data['links'] as $l){$host=(string)($l['hostname']?:'krvk.nl');$url='https://'.$host.'/'.(string)$l['slug'];$links.='<article class="beacon-row"><strong>'.self::e((string)$l['label']).'</strong><span>Link · '.(int)$l['visit_count'].' visits</span><a href="'.self::e($url).'">'.self::e($url).'</a><a class="quiet-button" href="/beacon">Edit soon</a></article>';}
        $pages='';foreach($data['pages'] as $p){$pages.='<article class="beacon-row"><strong>'.self::e((string)$p['title']).'</strong><span>'.self::e(ucfirst((string)$p['visibility'])).' · '.self::e(ucwords(str_replace('_',' ',(string)$p['page_type']))).'</span><a href="/beacon/pages/'.self::e((string)$p['id']).'/edit">Edit</a>'.($p['visibility']!=='private'?'<a href="/p/'.self::e((string)$p['page_key']).'">Public view</a>':'<span>Private draft</span>').'</article>';}
        $campaigns='';foreach($data['campaigns'] as $c)$campaigns.='<article class="surface"><p class="eyebrow">Beacon campaign · '.self::e(ucfirst((string)$c['status'])).'</p><h3>'.self::e((string)$c['title']).'</h3><p>'.self::e((string)($c['purpose']??'Public call to action')).'</p><p class="meta">Audience: '.self::e((string)($c['audience']??'Not specified')).' · Privacy-aware engagement '.(int)$c['engagement_count'].'</p><a href="/beacon/campaigns/'.self::e((string)$c['id']).'">Review campaign</a></article>';
        $pageOptions='<option value="">No page yet</option>';foreach($data['pages'] as $p)$pageOptions.='<option value="'.self::e((string)$p['id']).'">'.self::e((string)$p['title']).' ('.self::e((string)$p['visibility']).')</option>';
        $linkOptions='<option value="">No short link yet</option>';foreach($data['links'] as $l)$linkOptions.='<option value="'.self::e((string)$l['id']).'">'.self::e((string)$l['label']).'</option>';
        $presence='<section class="surface beacon-mission-control beacon-broad-presence-pass"><h2>Beacon Mission Control</h2><p>Beacon now presents its public toolkit in one place: short links, public pages, QR/action blocks, campaigns, domain routing, publication safety, revision history, and privacy-aware engagement. Beacon shares doorways; it does not own Gather RSVP, signup, attendance, or follow-up truth; Beacon campaigns never own RSVP.</p><p class="local-actions"><a href="/gather">Gather events</a><a href="/source-review">Source Review</a><a href="/privacy">Privacy boundaries</a></p></section>';
        $body='<section class="page-heading beacon-brand-hero"><div><p class="eyebrow">Beacon</p><h1>Share the right thing, cleanly.</h1><p>Short links use krvk.nl by default. Verified organization domains can become additional public doorways without changing the underlying Beacon record.</p></div></section>'.$this->commandOverview($data).$presence.'<section class="surface beacon-step-builder"><p class="eyebrow">Step-by-step Beacon builder</p><h2>Choose what this Beacon should do</h2><p>Start with the plain action people recognize: Link, Text, E-mail, Call, SMS, V-card, WhatsApp, WI-FI, PDF, App, Images, Video, Social Media, Event, or 2D Barcode. Each button is wired as a drawer-ready creation path so the next pass can slide the focused form in from the right.</p>'.$this->beaconTypeButtons().'</section><section class="surface beacon-domain-routing-console"><h2>Domain behavior</h2><p><strong>krvk.nl/</strong> redirects to <strong>koravik.com</strong>. A path such as <strong>krvk.nl/abc123</strong> resolves a Beacon. Future verified organization domains follow the same host-aware routing model.</p></section><section class="beacon-creation-studio"><article class="surface beacon-create-card"><p class="eyebrow">Doorway</p><h2>Create a short link</h2><p class="helper-text">Use this when you already have a destination and need a clean public doorway.</p><form method="post" action="/beacon/links"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Plain-language label<input name="label" maxlength="180" required placeholder="Fall volunteer signup, Sunday bulletin, Giving page"></label><label>Where should it send people?<input name="destination" type="url" required placeholder="https://example.org/page"></label><button class="button" type="submit">Create short link</button></form></article><article class="surface beacon-create-card"><p class="eyebrow">Public page</p><h2>Create a Beacon page</h2><p class="helper-text">Start private. Preview it. Publish only when the visible information is safe.</p><form method="post" action="/beacon/pages"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Page type<select name="type"><option value="link_hub">Multi-action Beacon</option><option value="business_card">Contact / V-card Beacon</option><option value="wifi">WI-FI Beacon</option><option value="event_landing">Event Beacon</option></select></label><label>Page title<input name="title" required placeholder="Community dinner links"></label><label class="full">Short summary<textarea name="summary" placeholder="What should visitors understand before they tap anything?"></textarea></label><label>Primary value<input name="value" placeholder="URL, contact detail, WI-FI note, media link, or event call-to-action"></label><button class="button" type="submit">Create private draft</button></form></article><article class="surface beacon-create-card beacon-campaign-panel"><p class="eyebrow">Campaign</p><h2>Create a Beacon campaign</h2><p class="helper-text">Group a call to action, a page or link, and engagement without owning RSVP or signup truth.</p><form method="post" action="/beacon/campaigns"><input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'"><label>Campaign title<input name="title" maxlength="180" required placeholder="Winter coat drive"></label><label class="full">Purpose<textarea name="purpose" maxlength="500" placeholder="What action are you inviting people to take?"></textarea></label><label>Audience<input name="audience" maxlength="180" placeholder="Parents, volunteers, members, neighbors"></label><label>Beacon page<select name="page_id">'.$pageOptions.'</select></label><label>Short link<select name="short_link_id">'.$linkOptions.'</select></label><button class="button" type="submit">Create campaign draft</button></form></article></section><section><div class="section-heading"><h2>Beacon campaigns</h2><span>Public calls to action</span></div><div class="grid">'.($campaigns?:'<article class="empty-state"><h3>No campaigns yet.</h3></article>').'</div></section><section class="surface beacon-compact-list"><div class="section-heading"><h2>Your Beacons</h2><span>Compact management list · statistics links next</span></div><div class="beacon-list">'.($pages.$links?:'<article class="empty-state"><h3>No Beacons yet.</h3></article>').'</div></section>';
        echo $this->page('Beacon',$body);
    }

    private function indexV2(): void
    {
        $a=Security::requireAccount();$data=(new BeaconService($this->database))->dashboard((string)$a['id']);
        $rows=$this->beaconManagementRows($data);$campaigns='';foreach($data['campaigns'] as $c)$campaigns.='<article class="beacon-mini-row"><strong>'.self::e((string)$c['title']).'</strong><span>'.self::e(ucfirst((string)$c['status'])).'</span><span>'.self::e((string)($c['audience']??'No audience')).'</span><a href="/beacon/campaigns/'.self::e((string)$c['id']).'">Edit</a></article>';
        $body='<section class="beacon-home"><div class="beacon-home-top"><div><p class="eyebrow">Beacon</p><h1>Make a shareable thing.</h1><p>Pick a type. Fill the drawer. Publish when it looks right.</p></div><a class="button secondary" href="#your-beacons">View Beacons</a></div><section class="beacon-create-flow surface"><div class="beacon-step-label"><span>1</span><div><h2>Choose a Beacon type</h2><p>No templates to decode. Start with what people need to do.</p></div></div>'.$this->beaconTypeButtons('/beacon#beacon-drawer-').'</section><section id="your-beacons" class="surface beacon-file-table"><div class="beacon-table-head"><div><h2>Your Beacons</h2><p>Compact list now. Statistics links land here next.</p></div><span>'.(count($data['pages'])+count($data['links'])).' total</span></div><div class="beacon-file-table-grid" role="table" aria-label="Your Beacons"><div class="beacon-file-row beacon-file-header" role="row"><span>Name</span><span>Type</span><span>Link</span><span>Status</span><span></span></div>'.($rows?:'<article class="beacon-file-empty">No Beacons yet. Choose a type above.</article>').'</div></section><section class="surface beacon-campaign-strip"><div class="beacon-table-head"><div><h2>Campaigns</h2><p>Optional groups for public calls to action.</p></div><a href="#beacon-campaign-form">New campaign</a></div><div class="beacon-mini-list">'.($campaigns?:'<article class="beacon-file-empty">No campaigns yet.</article>').'</div></section><section id="beacon-campaign-form" class="surface beacon-slim-form"><h2>New campaign</h2><form method="post" action="/beacon/campaigns">'.$this->csrfField().'<label>Title<input name="title" maxlength="180" required placeholder="Winter coat drive"></label><label>Purpose<textarea name="purpose" maxlength="500" placeholder="What should people do?"></textarea></label><label>Audience<input name="audience" maxlength="180" placeholder="Parents, volunteers, neighbors"></label><button class="button">Create campaign</button></form></section></section>'.$this->beaconHomeDrawers().$this->beaconDrawerScript();
        echo $this->page('Beacon',$body);
    }

    private function beaconManagementRows(array $data): string
    {
        $rows='';foreach($data['pages'] as $p){$public=$p['visibility']!=='private'?'/p/'.(string)$p['page_key']:'Private draft';$rows.='<article class="beacon-file-row" role="row"><strong>'.self::e((string)$p['title']).'</strong><span>'.self::e($this->beaconTypeLabel((string)$p['page_type'])).'</span><span>'.($p['visibility']!=='private'?'<a href="'.self::e($public).'">'.self::e($public).'</a>':'Private draft').'</span><span>'.self::e(ucfirst((string)$p['visibility'])).'</span><a href="/beacon/pages/'.self::e((string)$p['id']).'/edit">Edit</a></article>';}
        foreach($data['links'] as $l){$host=(string)($l['hostname']?:'krvk.nl');$url='https://'.$host.'/'.(string)$l['slug'];$rows.='<article class="beacon-file-row" role="row"><strong>'.self::e((string)$l['label']).'</strong><span>Link</span><span><a href="'.self::e($url).'">'.self::e($url).'</a></span><span>'.(int)$l['visit_count'].' visits</span><a href="/beacon">Stats soon</a></article>';}
        return $rows;
    }

    private function beaconHomeDrawers(): string
    {
        $html='<div class="beacon-drawer-scrim" data-beacon-close hidden></div><section class="beacon-drawer-stack" aria-label="Create Beacon forms">';
        foreach(BeaconService::BEACON_ACTION_TYPES as $type){$label=$this->beaconTypeLabel($type);$copy=$this->beaconTypeFormCopy($type);$html.='<aside class="beacon-type-drawer" id="beacon-drawer-'.self::e($type).'" data-beacon-drawer="'.self::e($type).'" aria-hidden="true" hidden><div class="beacon-drawer-header"><p class="eyebrow">New '.self::e($label).'</p><button class="quiet-button" type="button" data-beacon-close>Close</button></div><h2>'.self::e($copy['heading']).'</h2><form method="post" action="/beacon/actions">'.$this->csrfField().'<input type="hidden" name="block_type" value="'.self::e($type).'"><label>Name<input name="title" maxlength="180" required placeholder="'.self::e($copy['title']).'"></label><label>Short note<textarea name="body" placeholder="'.self::e($copy['body']).'"></textarea></label><label>Button text<input name="action_label" maxlength="120" placeholder="'.self::e($copy['action_label']).'"></label><label>Value / URL<input name="action_value" maxlength="500" placeholder="'.self::e($copy['action_value']).'"></label><button class="button">Create Beacon</button></form></aside>';}
        return $html.'</section>';
    }

    private function commandOverview(array $data): string
    {
        $links=count($data['links']??[]);$pages=count($data['pages']??[]);$campaigns=count($data['campaigns']??[]);$qrs=count($data['qrs']??[]);
        return '<section class="beacon-command-overview surface"><div><p class="eyebrow">Beacon Command Overview</p><h2>Publishing, links, campaigns, QR, and domains stay here.</h2><p>Beacon is the public-facing doorway layer. It can point to Gather, Chronicle, Quests, or outside resources, but the original truth stays with the source.</p></div><dl><div><dt>Short links</dt><dd>'.$links.'</dd></div><div><dt>Pages</dt><dd>'.$pages.'</dd></div><div><dt>Campaigns</dt><dd>'.$campaigns.'</dd></div><div><dt>QR definitions</dt><dd>'.$qrs.'</dd></div></dl><ol class="beacon-pipeline-steps"><li><strong>1 · Make the doorway</strong><span>Create a short link or private page draft.</span></li><li><strong>2 · Preview safely</strong><span>Check exactly what a visitor will see.</span></li><li><strong>3 · Publish deliberately</strong><span>Choose unlisted or public only after review.</span></li></ol></section>';
    }

    private function beaconTypeButtons(string $prefix='/beacon#beacon-drawer-'): string
    {
        $labels=['link'=>'Link','text'=>'Text','email'=>'E-mail','call'=>'Call','sms'=>'SMS','vcard'=>'V-card','whatsapp'=>'WhatsApp','wifi'=>'WI-FI','pdf'=>'PDF','app'=>'App','image'=>'Images','video'=>'Video','social_media'=>'Social Media','event'=>'Event','barcode_2d'=>'2D Barcode'];$html='<div class="beacon-type-grid">';
        foreach(BeaconService::BEACON_ACTION_TYPES as $type)$html.='<a class="beacon-type-button" href="'.self::e($prefix.$type).'"><span>'.self::e($labels[$type]??$type).'</span><small>'.self::e($this->beaconTypeHint($type)).'</small></a>';
        return $html.'</div>';
    }

    private function beaconBlockOptions(): string
    {
        $labels=['link'=>'Link','text'=>'Text','email'=>'E-mail','call'=>'Call','sms'=>'SMS','vcard'=>'V-card','whatsapp'=>'WhatsApp','wifi'=>'WI-FI','pdf'=>'PDF','app'=>'App','image'=>'Images','video'=>'Video','social_media'=>'Social Media','event'=>'Event','barcode_2d'=>'2D Barcode'];$html='';
        foreach(BeaconService::BEACON_ACTION_TYPES as $type)$html.='<option value="'.self::e($type).'">'.self::e($labels[$type]??$type).'</option>';
        return $html;
    }

    private function beaconTypeHint(string $type): string
    {
        return match($type){'email'=>'mailto action','call'=>'tap to call','sms'=>'tap to text','vcard'=>'save contact','whatsapp'=>'chat link','wifi'=>'network card','pdf'=>'document link','app'=>'app store/deep link','image'=>'image gallery','video'=>'video embed/link','social_media'=>'social profile','event'=>'event CTA','barcode_2d'=>'QR/Data Matrix','text'=>'public note',default=>'web destination'};
    }

    private function beaconTypeLabel(string $type): string
    {
        return ['link'=>'Link','text'=>'Text','email'=>'E-mail','call'=>'Call','sms'=>'SMS','vcard'=>'V-card','whatsapp'=>'WhatsApp','wifi'=>'WI-FI','pdf'=>'PDF','app'=>'App','image'=>'Images','video'=>'Video','social_media'=>'Social Media','event'=>'Event','barcode_2d'=>'2D Barcode'][$type]??ucwords(str_replace('_',' ',$type));
    }

    private function beaconDrawerPanels(string $pageId): string
    {
        $html='<div class="beacon-drawer-scrim" data-beacon-close hidden></div><section class="beacon-drawer-stack" aria-label="Beacon type forms">';
        foreach(BeaconService::BEACON_ACTION_TYPES as $type){$label=$this->beaconTypeLabel($type);$copy=$this->beaconTypeFormCopy($type);$html.='<aside class="beacon-type-drawer" id="beacon-drawer-'.self::e($type).'" data-beacon-drawer="'.self::e($type).'" aria-hidden="true" hidden><div class="beacon-drawer-header"><p class="eyebrow">Step 3 · '.self::e($label).'</p><button class="quiet-button" type="button" data-beacon-close>Close</button></div><h2>'.self::e($copy['heading']).'</h2><p>'.self::e($copy['help']).'</p><form method="post" action="/beacon/pages/'.self::e($pageId).'/blocks">'.$this->csrfField().'<input type="hidden" name="block_type" value="'.self::e($type).'"><label>Public label<input name="title" maxlength="180" required placeholder="'.self::e($copy['title']).'"></label><label>Explanation<textarea name="body" placeholder="'.self::e($copy['body']).'"></textarea></label><label>Button label<input name="action_label" maxlength="120" placeholder="'.self::e($copy['action_label']).'"></label><label>Value or destination<input name="action_value" maxlength="500" placeholder="'.self::e($copy['action_value']).'"></label><button class="button">Add '.self::e($label).' Beacon</button></form></aside>';}
        return $html.'</section>';
    }

