    private function beaconDrawerScript(): string
    {
        return '<script>document.addEventListener("click",function(e){const opener=e.target.closest(".beacon-type-button");const closer=e.target.closest("[data-beacon-close]");const closeDrawers=()=>{document.querySelectorAll(".beacon-type-drawer").forEach(d=>{d.setAttribute("aria-hidden","true");d.setAttribute("hidden","")});document.querySelector(".beacon-drawer-scrim")?.setAttribute("hidden","")};if(opener){const href=opener.getAttribute("href")||"";const id=href.includes("#")?href.slice(href.indexOf("#")):href;const drawer=id?document.querySelector(id):null;if(drawer){e.preventDefault();closeDrawers();drawer.removeAttribute("hidden");drawer.setAttribute("aria-hidden","false");document.querySelector(".beacon-drawer-scrim")?.removeAttribute("hidden");drawer.querySelector("input:not([type=hidden]),textarea,select,button")?.focus();}}if(closer)closeDrawers();});document.addEventListener("keydown",function(e){if(e.key==="Escape"){document.querySelectorAll(".beacon-type-drawer").forEach(d=>{d.setAttribute("aria-hidden","true");d.setAttribute("hidden","")});document.querySelector(".beacon-drawer-scrim")?.setAttribute("hidden","");}});</script>';
    }

    private function createLink(): void{$this->csrf();$a=Security::requireAccount();try{(new BeaconService($this->database))->createLink((string)$a['id'],(string)($_POST['label']??''),(string)($_POST['destination']??''));$_SESSION['flash']='Short link created.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/beacon');}
