    private function createCampaign(): void{$this->csrf();$a=Security::requireAccount();try{$id=(new BeaconService($this->database))->createCampaign((string)$a['id'],$_POST);$_SESSION['flash']='Beacon campaign draft created.';$this->go('/beacon/campaigns/'.$id);}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/beacon');}
    private function campaign(string $id): void{$a=Security::requireAccount();try{$c=(new BeaconService($this->database))->campaign((string)$a['id'],$id);}catch(RuntimeException $e){http_response_code(404);echo $this->page('Campaign unavailable','<section class="empty-state"><h1>'.self::e($e->getMessage()).'</h1></section>');return;}$body=$this->flash().'<section class="page-heading beacon-campaign-pipeline"><div><p class="eyebrow">Beacon campaign · Public Call-to-Action Pipeline</p><h1>'.self::e((string)$c['title']).'</h1><p>Manage the public call to action without taking ownership from Gather, Quests, or Chronicle.</p></div><a href="/beacon">Back to Beacon</a></section><div class="beacon-builder"><form class="surface" method="post" action="/beacon/campaigns/'.self::e($id).'">'.$this->csrfField().'<label>Title<input name="title" maxlength="180" required value="'.self::e((string)$c['title']).'"></label><label>Purpose<textarea name="purpose" maxlength="500">'.self::e((string)($c['purpose']??'')).'</textarea></label><label>Audience<input name="audience" maxlength="180" value="'.self::e((string)($c['audience']??'')).'"></label><label>Status<select name="status"><option value="draft"'.($c['status']==='draft'?' selected':'').'>Draft</option><option value="active"'.($c['status']==='active'?' selected':'').'>Active</option><option value="paused"'.($c['status']==='paused'?' selected':'').'>Paused</option><option value="archived"'.($c['status']==='archived'?' selected':'').'>Archived</option></select></label><section class="beacon-publish-warning beacon-public-trust-layer"><h2>Before activating</h2><p>Beacon Public Trust Layer: public campaign content can send people to a Beacon page or link. RSVP, signup, attendance, guest identities, and personal follow-up remain owned by their source modules.</p></section><button class="button">Save campaign</button></form><aside><section class="surface"><h2>Campaign preview</h2><p class="eyebrow">'.self::e(ucfirst((string)$c['status'])).'</p><h3>'.self::e((string)$c['title']).'</h3><p>'.self::e((string)($c['purpose']??'')).'</p><dl><div><dt>Page</dt><dd>'.self::e((string)($c['page_title']??'None')).'</dd></div><div><dt>Link</dt><dd>'.self::e((string)($c['link_label']??'None')).'</dd></div><div><dt>Privacy-aware engagement</dt><dd>'.(int)$c['engagement_count'].'</dd></div></dl></section></aside></div>';echo $this->page('Beacon campaign',$body);}
    private function updateCampaign(string $id): void{$this->csrf();$a=Security::requireAccount();try{(new BeaconService($this->database))->updateCampaign((string)$a['id'],$id,$_POST);$_SESSION['flash']='Beacon campaign updated.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/beacon/campaigns/'.$id);}
    private function editPage(string $id):void{$a=Security::requireAccount();$p=(new BeaconService($this->database))->ownedPage((string)$a['id'],$id);if(!$p){http_response_code(404);echo $this->page('Page unavailable','<section class="empty-state"><h1>That Beacon page is unavailable.</h1></section>');return;}$value=(string)($p['payload']['value']??'');$history='';foreach($p['revisions'] as $r)$history.='<li>'.self::e(ucfirst((string)$r['action'])).' · '.self::e((string)$r['created_at']).' UTC</li>';$blocks='';foreach(($p['blocks']??[]) as $b){$bid=self::e((string)$b['id']);$blocks.='<article class="beacon-block-preview"><p class="eyebrow">'.self::e(str_replace('_',' ',(string)$b['block_type'])).'</p><h3>'.self::e((string)($b['title']??'')).'</h3><p>'.self::e((string)($b['body']??'')).'</p>'.($b['action_value']?'<a class="button secondary" href="'.self::e((string)$b['action_value']).'">'.self::e((string)($b['action_label']?:'Open')).'</a>':'').'<div class="inline-actions"><form method="post" action="/beacon/pages/'.self::e($id).'/blocks/'.$bid.'/up">'.$this->csrfField().'<button class="quiet-button">Move up</button></form><form method="post" action="/beacon/pages/'.self::e($id).'/blocks/'.$bid.'/down">'.$this->csrfField().'<button class="quiet-button">Move down</button></form></div></article>';}$preview='<article class="beacon-phone-preview"><p class="eyebrow">'.self::e(ucwords(str_replace('_',' ',(string)$p['page_type']))).'</p><h2>'.self::e((string)$p['title']).'</h2><p>'.self::e((string)$p['summary']).'</p>'.($value!==''?'<p class="prominent-value">'.self::e($value).'</p>':'').$blocks.'</article>';$body='<section class="page-heading beacon-builder-hero"><div><p class="eyebrow">Beacon page builder · Publishing workflow</p><h1>'.self::e((string)$p['title']).'</h1><p>Build a page from bounded text, links, contact details, event calls-to-action, and QR/action blocks. Preview first, reorder intentionally, then publish only what should be public. Beacon page block reordering + publishing checks keep this workflow deliberate.</p></div><a href="/beacon">Back to Beacon</a></section><section class="beacon-builder-guidance surface"><h2>Page builder steps</h2><ol class="beacon-pipeline-steps"><li><strong>1 · Edit the visible page</strong><span>Title, summary, primary value, and visibility.</span></li><li><strong>2 · Add blocks</strong><span>Use templates for text, link, contact, event, or QR/action.</span></li><li><strong>3 · Review the phone preview</strong><span>Publish only after checking the public view.</span></li></ol></section><div class="beacon-builder"><div><form class="surface beacon-page-editor" method="post" action="/beacon/pages/'.self::e($id).'">'.$this->csrfField().'<p class="eyebrow">Page details</p><h2>Edit visible page content</h2><label>Title<input name="title" maxlength="180" required value="'.self::e((string)$p['title']).'"></label><label>Summary<textarea name="summary">'.self::e((string)$p['summary']).'</textarea></label><label>Primary value<input name="value" value="'.self::e($value).'"></label><label>Visibility<select name="visibility"><option value="private"'.($p['visibility']==='private'?' selected':'').'>Private draft</option><option value="unlisted"'.($p['visibility']==='unlisted'?' selected':'').'>Anyone with the link</option><option value="public"'.($p['visibility']==='public'?' selected':'').'>Public</option></select></label><section class="beacon-publish-warning unified-public-preview-safety"><h2>Before publishing</h2><p>Unified Public Preview Safety: unlisted and public pages may expose every value shown in this preview. Do not publish passwords, private contact details, RSVP truth, or information you do not intend to share.</p></section><button class="button">Save page and visibility</button></form><form class="surface beacon-block-composer" method="post" action="/beacon/pages/'.self::e($id).'/blocks">'.$this->csrfField().'<p class="eyebrow">Add block</p><h2>Add a public content block</h2><p class="helper-text">Beacon public page blocks should be short, obvious, and safe to show to anyone with access.</p><div class="beacon-block-template-strip" aria-label="Common Beacon blocks"><span>Announcement text</span><span>Button link</span><span>Contact card</span><span>Event CTA</span><span>QR action</span></div><label>Block type<select name="block_type"><option value="text">Text</option><option value="link">Link</option><option value="contact">Contact</option><option value="event">Event</option><option value="qr_action">QR/action</option></select></label><label>Title<input name="title" maxlength="180" placeholder="Register, Contact us, What to bring"></label><label>Body<textarea name="body" placeholder="Short, public-safe instructions or explanation"></textarea></label><label>Action label<input name="action_label" maxlength="120" placeholder="Open signup, Email organizer, Get directions"></label><label>Action value<input name="action_value" maxlength="500" placeholder="https://..., mailto:..., tel:..."></label><button class="button secondary">Add block</button></form></div><aside><p class="eyebrow">Mobile preview</p>'.$preview.'<section class="surface beacon-revision-card"><h2>Revision history</h2><ul>'.($history?:'<li>No revisions yet.</li>').'</ul></section></aside></div>';$this->page('Edit Beacon page',$body);}
    private function editPageV2(string $id):void
    {
        $a=Security::requireAccount();$p=(new BeaconService($this->database))->ownedPage((string)$a['id'],$id);
        if(!$p){http_response_code(404);echo $this->page('Page unavailable','<section class="empty-state"><h1>That Beacon page is unavailable.</h1></section>');return;}
        $value=(string)($p['payload']['value']??'');$history='';foreach($p['revisions'] as $r)$history.='<li>'.self::e(ucfirst((string)$r['action'])).' · '.self::e((string)$r['created_at']).' UTC</li>';
        $blocks='';foreach(($p['blocks']??[]) as $b){$bid=self::e((string)$b['id']);$blocks.='<article class="beacon-block-preview"><p class="eyebrow">'.self::e($this->beaconTypeLabel((string)$b['block_type'])).'</p><h3>'.self::e((string)($b['title']??'')).'</h3><p>'.self::e((string)($b['body']??'')).'</p>'.($b['action_value']?'<a class="button secondary" href="'.self::e((string)$b['action_value']).'">'.self::e((string)($b['action_label']?:'Open')).'</a>':'').'<div class="inline-actions"><form method="post" action="/beacon/pages/'.self::e($id).'/blocks/'.$bid.'/up">'.$this->csrfField().'<button class="quiet-button">Move up</button></form><form method="post" action="/beacon/pages/'.self::e($id).'/blocks/'.$bid.'/down">'.$this->csrfField().'<button class="quiet-button">Move down</button></form></div></article>';}
        $preview='<article class="beacon-phone-preview"><p class="eyebrow">'.self::e(ucwords(str_replace('_',' ',(string)$p['page_type']))).'</p><h2>'.self::e((string)$p['title']).'</h2><p>'.self::e((string)$p['summary']).'</p>'.($value!==''?'<p class="prominent-value">'.self::e($value).'</p>':'').$blocks.'</article>';
        $body='<section class="page-heading beacon-builder-hero"><div><p class="eyebrow">Beacon page builder · Publishing workflow</p><h1>'.self::e((string)$p['title']).'</h1><p>Step 1: edit page details. Step 2: choose the Beacon type. Step 3: fill the drawer form. Step 4: preview and publish. Beacon page block reordering + publishing checks keep this workflow deliberate.</p></div><a href="/beacon">Back to Beacon</a></section>';
        $body.='<section class="beacon-builder-guidance surface"><h2>Page builder steps</h2><ol class="beacon-pipeline-steps"><li><strong>1 · Page basics</strong><span>Title, summary, value, and visibility.</span></li><li><strong>2 · Choose action</strong><span>Pick Link, Text, E-mail, Call, SMS, V-card, WhatsApp, WI-FI, PDF, App, Images, Video, Social Media, Event, or 2D Barcode.</span></li><li><strong>3 · Drawer form</strong><span>Fill only the fields for that Beacon type.</span></li><li><strong>4 · Preview safely</strong><span>Publish only after checking the public view.</span></li></ol></section>';
        $body.='<div class="beacon-builder"><div><form class="surface beacon-page-editor" method="post" action="/beacon/pages/'.self::e($id).'">'.$this->csrfField().'<p class="eyebrow">Step 1 · Page details</p><h2>Edit visible page content</h2><label>Title<input name="title" maxlength="180" required value="'.self::e((string)$p['title']).'"></label><label>Summary<textarea name="summary">'.self::e((string)$p['summary']).'</textarea></label><label>Primary value<input name="value" value="'.self::e($value).'"></label><label>Visibility<select name="visibility"><option value="private"'.($p['visibility']==='private'?' selected':'').'>Private draft</option><option value="unlisted"'.($p['visibility']==='unlisted'?' selected':'').'>Anyone with the link</option><option value="public"'.($p['visibility']==='public'?' selected':'').'>Public</option></select></label><section class="beacon-publish-warning unified-public-preview-safety"><h2>Before publishing</h2><p>Unified Public Preview Safety: unlisted and public pages may expose every value shown in this preview. Do not publish passwords, private contact details, RSVP truth, or information you do not intend to share.</p></section><button class="button">Save page and visibility</button></form>';
        $body.='<section class="surface beacon-block-composer"><p class="eyebrow">Step 2 · Add a Beacon action</p><h2>Choose the action type</h2><p class="helper-text">Each button opens a focused right-side drawer. The fallback dropdown form is still below, so the builder remains usable without JavaScript.</p><div class="beacon-drawer-launchers">'.$this->beaconTypeButtons('#beacon-drawer-').'</div><form class="beacon-fallback-block-form" method="post" action="/beacon/pages/'.self::e($id).'/blocks">'.$this->csrfField().'<label>Block type<select name="block_type">'.$this->beaconBlockOptions().'</select></label><label>Title<input name="title" maxlength="180" placeholder="Register, Contact us, What to bring"></label><label>Body<textarea name="body" placeholder="Short, public-safe instructions or explanation"></textarea></label><label>Action label<input name="action_label" maxlength="120" placeholder="Open signup, Email organizer, Get directions"></label><label>Action value<input name="action_value" maxlength="500" placeholder="URL, mailto:, tel:, sms:, WhatsApp, Wi-Fi note, media link, event URL, or barcode data"></label><button class="button secondary">Add block</button></form></section>'.$this->beaconDrawerPanels($id).'</div><aside><p class="eyebrow">Mobile preview</p>'.$preview.'<section class="surface beacon-revision-card"><h2>Revision history</h2><ul>'.($history?:'<li>No revisions yet.</li>').'</ul></section></aside></div>'.$this->beaconDrawerScript();
        echo $this->page('Edit Beacon page',$body);
    }
    private function updatePage(string $id):void{$this->csrf();$a=Security::requireAccount();try{(new BeaconService($this->database))->updatePage((string)$a['id'],$id,$_POST);$_SESSION['flash']='Beacon page and visibility updated.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/beacon/pages/'.$id.'/edit');}
    private function addBlock(string $id):void{$this->csrf();$a=Security::requireAccount();try{(new BeaconService($this->database))->addBlock((string)$a['id'],$id,$_POST);$_SESSION['flash']='Beacon page block added.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/beacon/pages/'.$id.'/edit');}
    private function moveBlock(string $id,string $block,string $direction):void{$this->csrf();$a=Security::requireAccount();try{(new BeaconService($this->database))->moveBlock((string)$a['id'],$id,$block,$direction);$_SESSION['flash']='Beacon page block reordered.';}catch(RuntimeException $e){$_SESSION['flash']=$e->getMessage();}$this->go('/beacon/pages/'.$id.'/edit');}
    private function redirectLink(string $slug): void{$row=(new BeaconService($this->database))->resolve($slug);if(!$row){http_response_code(404);echo $this->page('Link not found','<section class="empty-state"><h1>This Beacon is unavailable.</h1></section>');return;}header('Location: '.(string)$row['destination_url'],true,302);exit;}
    private function publicPage(string $key): void{$p=(new BeaconService($this->database))->page($key);if(!$p){http_response_code(404);echo $this->page('Page not found','<section class="empty-state"><h1>This Beacon page is unavailable.</h1></section>');return;}$payload=$p['payload'];$value=self::e((string)($payload['value']??''));$blocks='';foreach(($p['blocks']??[]) as $b)$blocks.='<article class="beacon-public-block"><p class="eyebrow">'.self::e(str_replace('_',' ',(string)$b['block_type'])).'</p><h2>'.self::e((string)($b['title']??'')).'</h2><p>'.self::e((string)($b['body']??'')).'</p>'.($b['action_value']?'<a class="button secondary" href="'.self::e((string)$b['action_value']).'">'.self::e((string)($b['action_label']?:'Open')).'</a>':'').'</article>';$body='<div class="beacon-public-shell beacon-public-presence-layer"><section class="public-beacon beacon-public-card"><p class="eyebrow">'.self::e(ucwords(str_replace('_',' ',(string)$p['page_type']))).' · Beacon public presence</p><h1>'.self::e((string)$p['title']).'</h1><p>'.self::e((string)($p['summary']??'')).'</p>'.($value!==''?'<p class="prominent-value">'.$value.'</p>':'').$blocks.'<section class="beacon-public-source-boundary"><h2>Source boundary</h2><p>Beacon presents this page. Source modules own the original RSVP, signup, attendance, contact, payment, or follow-up truth behind any linked action.</p></section><p class="beacon-source-note">Shared through Beacon · '.self::e(ucfirst((string)$p['visibility'])).' · Public view stays intentionally bounded.</p></section></div>';echo $this->page((string)$p['title'],$body);}
    private function csrf():void{if(!Security::verifyCsrf((string)($_POST['csrf']??'')))throw new RuntimeException('Your session token expired.');}
    private function go(string $to):never{header('Location: '.$to,true,303);exit;}
    private function csrfField():string{return '<input type="hidden" name="csrf" value="'.self::e(Security::csrfToken()).'">';}
    private function page(string $title,string $body):string{$flash='';if(isset($_SESSION['flash'])){$flash='<div class="notice">'.self::e((string)$_SESSION['flash']).'</div>';unset($_SESSION['flash']);}return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.self::e($title).' · Koravik</title><link rel="stylesheet" href="/assets/app.css"><link rel="stylesheet" href="/assets/journey.css"><link rel="stylesheet" href="/assets/beacon-builder.css?v=beacon-dashboard-v3"></head><body><main id="main" class="page beacon-broad-stroke-presence">'.$flash.$body.'</main><footer>Koravik · Beacon</footer></body></html>';}
    private static function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
}
